void supabase
  .from('handover_slips')
  .select('from_department_id, colorway_id, status, sent_qty, received_qty')
  .eq('factory_id', factoryId)
  .eq('order_id', selectedOrderId)
  .then((slipsRes) => {
    if (!cancelled) {
      setHandoverSlips((slipsRes.data || []) as Array<Record<string, unknown>>);
    }
  });

